create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SVMARA_EKS_ITEM_CASEGROSSWEIGHT_MISSINGSEL(
	NEGOTIATINGCOUNTRY,
	BUYERSHORTSIGN,
	BUYERFIRSTNAME,
	BUYERLASTNAME,
	ZMATKL,
	ARTICLEFAMILY,
	ITEMID,
	ITEMNO,
	ARTICLETYPE,
	DESCRIPTION,
	LISTINGOVERVIEWID,
	SUPPLIERNO,
	SUPPLIERDESCRIPTION,
	RECEIVINGCOUNTRY,
	ZRELEVANTMDM,
	ZSOURCE,
	ZACTIVE
) as
(SELECT DISTINCT
						  EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry AS NegotiatingCountry,
						  EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN,
						  EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName,
						  EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName,
						  EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL,
						  EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily,
						  EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID,
						  EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO,
						  EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType AS ArticleType,
						  EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT as Description,
						  EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.LISTINGOVERVIEWID,
						  EKS.SUPPLIER.INTSUPPLIERNO AS SUPPLIERNO,
						  EKS.SUPPLIER.DESCRIPTION AS SupplierDescription,
						  EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.ReceivingCountry,
						  EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.zIsWAWIRelevant AS zRelevantMDM,
						  EKS_CALCULATION.stMARA_EKS_ITEM.zSource,
						  EKS_CALCULATION.stMARA_EKS_ITEM.zActive
FROM     EKS_CALCULATION.stMARA_EKS_ITEM INNER JOIN
EKS.SUPPLIER INNER JOIN
EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX ON EKS.SUPPLIER.SUPPLIERNO = EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.SUPPLIERNO
ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID = EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.ITEMID INNER JOIN
EKS_CALCULATION.xtEKS_BASICINFO_UNION ON EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.LISTINGOVERVIEWID = EKS_CALCULATION.xtEKS_BASICINFO_UNION.LISTINGOVERVIEWID AND EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.CaseSize = EKS_CALCULATION.xtEKS_BASICINFO_UNION.casesize AND EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_UNION.itemid AND EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.ReceivingCountry = EKS_CALCULATION.xtEKS_BASICINFO_UNION.RecievingCountry LEFT OUTER JOIN
EKS.ITEMWEIGHT ON EKS_CALCULATION.xtEKS_BASICINFO_UNION.CONTRACTPRICEVALIDITYID = EKS.ITEMWEIGHT.CONTRACTPRICEVALIDITYID AND EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.ITEMID = EKS.ITEMWEIGHT.ITEMID INNER JOIN
EKS_CALCULATION.xtEKS_BASICINFO_RecCountry ON EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.LISTINGOVERVIEWID = EKS_CALCULATION.xtEKS_BASICINFO_UNION.LISTINGOVERVIEWID AND EKS_CALCULATION.xtEKS_BASICINFO_UNION.casesize = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.casesize AND EKS.SUPPLIER.SUPPLIERNO = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SUPPLIERNO AND  EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.ReceivingCountry = EKS_CALCULATION.xtEKS_BASICINFO_UNION.RecievingCountry AND (EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.itemid = EKS_CALCULATION.xtEKS_BASICINFO_UNION.itemid AND EKS_CALCULATION.xtEKS_BASICINFO_UNION.zArticleType = 'EA' OR EKS_CALCULATION.xtEKS_BASICINFO_UNION.zArticleType = 'SK' AND EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_ITEMID) AND EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.BASICPRICEID = EKS_CALCULATION.xtEKS_BASICINFO_UNION.BASICPRICEID INNER JOIN
EKS.LISTINGOVERVIEW AS list ON EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.LISTINGOVERVIEWID = list.LISTINGOVERVIEWID AND EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SUPPLIERNO = list.SUPPLIERNO LEFT OUTER JOIN
EKS.LOCATEGORY AS loc ON list.LOCATEGORYID = loc.LOCATEGORYID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS trans_loc ON loc.DESCRIPTIONID = trans_loc.TRANSLATIONID LEFT OUTER JOIN
EKS_CALCULATION.EKS_ZSM_ExcludeList ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO AND ( ( EKS.SUPPLIER.INTSUPPLIERNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) OR ( EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID AND EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL ) OR ( EKS.SUPPLIER.INTSUPPLIERNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO AND EKS_CALCULATION.stEKS_LISTINGOVERVIEWMAX.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID ) OR ( EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) ) AND EKS_CALCULATION.EKS_ZSM_ExcludeList.REPORTNO = '023'
WHERE  ((EKS.ITEMWEIGHT.CASEGROSSWEIGHT IS NULL) AND (EKS_CALCULATION.stMARA_EKS_ITEM.Constructed IS NULL) AND (EKS_CALCULATION.stMARA_EKS_ITEM.zIsCurrentContract = 1) AND (LOWER(trans_loc.DESCRIPTION) NOT LIKE '%filialbelieferung%') OR (EKS.ITEMWEIGHT.CASEGROSSWEIGHT IS NULL) AND (EKS_CALCULATION.stMARA_EKS_ITEM.Constructed IS NULL) AND (LOWER(trans_loc.DESCRIPTION) NOT LIKE '%filialbelieferung%') AND (EKS_CALCULATION.stMARA_EKS_ITEM.zIsCurrentContractFromSK = 1)) AND ( EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO IS NULL
 AND EKS_CALCULATION.stMARA_EKS_ITEM.zActive = 1)
);